# -*- coding: utf-8 -*-
"""
This module provides handlers with decorators that inject implicit alias lookup and
their helpers.
"""
from .replace_args import ArgumentReplacer
from .stores import Store
from functools import wraps, partial


class LookupHandler(object):
    """Main class of the library.

    This class handles decoration of methods and functions, and provides backreferences
    of store implementations to the decorated subroutines. Within class definitions, it
    can only be used statically, i.e. all of the instances of the class will share the
    same store.

    Attributes
    ----------

    store : Store
        This attribute contains the store that is used when decorated instances try to
        resolve the alias given to them. If the assigned value is not an instance of
        :class:`Store`, raises ``ValueError``.

    Parameters
    ----------
    lookup_arg : :class:`str`, optional
        Default name of the argument via which the aliases will be passed. Used if no
        argument name is passed to implicit_lookup decorator.

    lookup_type : :class:`type` or a tuple of types, optional
        If the value passed via decorated function's aliased parameter (the one
        designated by the ``lookup_arg``) is an instance of this type, it will be
        passed as is, without interpreting it as an alias. If omitted, the value passed
        will always be used as a lookup key in the store.

        This is used to provide backward-compatibility for functions that already use
        arguments to pass objects that will be aliased.
    """
    def __init__(self, lookup_arg=None, lookup_type=None):
        self._store = None
        self.lookup_arg = lookup_arg
        self._lookup_type = lookup_type

    @property
    def store(self):
        return self._store

    @store.setter
    def store(self, new_store):
        if not isinstance(new_store, Store):
            raise ValueError("must be an instance of Store.")
        self._store = new_store

    def implicit_lookup(self, arg_name_or_func):
        """Make subroutine treat an argument as an alias.

        This is a decorator.

        Parameters
        ----------
        arg_name_or_func : :class:`str`, optional
            A string with the name of the argument to treat as the lookup one. If given,
            this overrides the argument set via ``lookup_arg`` in this class'
            ``__init__`` method.

        Raises
        ------
        TypeError
            If the decorated function does not have the specified argument in its
            signature.

        RuntimeError
            If the handler has no store set.

        Note
        ----
        In Python 2 the decorated function looses its signature information (its
        parameters are seen as ``*args, **kwargs``).

        Example
        -------

        Use this method as a decorator::

            handler = LookupHandler('lookup_argument')

            @handler.implicit_lookup
            def decorated_func(lookup_argument):
                ...

            @handler.implicit_lookup('nondefault_argument')
            def decorated_func(nondefault_argument):
                ...

        This will add the lookup mechanism to the method / function. The specified
        parameter will now be treated as a key to the alias lookup.

        Each time the decorated subroutine is called, if the argument value is
        not of ``lookup_type`` type (see above), it will be first looked up in the
        handler's `store`_, and replaced with the actual instance that is found there.

        The rest of the arguments are passed as is.

        If the lookup handler's store is changed, the decorated functions will use the
        new one.
        """

        simple_decoration = callable(arg_name_or_func)
        if simple_decoration:
            if self.lookup_arg is None:
                self._raise_no_default_argname()
            subroutine = arg_name_or_func
            return self._implicit_lookup(subroutine, self.lookup_arg)
        else:
            lookup_arg = arg_name_or_func
            return partial(self._implicit_lookup, arg_name=lookup_arg)

    def _implicit_lookup(self, subroutine, arg_name):
        replacer = ArgumentReplacer(subroutine, arg_name)

        @wraps(subroutine)
        def lookup_closure(*args, **kwargs):
            with replacer.replace_and_call(args, kwargs) as replaced:
                if self._should_be_replaced(replaced.value):
                    self._lookup_in_store_and_replace_argument(replaced)
            return replaced.returned_value
        return lookup_closure

    def _should_be_replaced(self, current_value):
        return (
            self._lookup_type is None
            or not isinstance(current_value, self._lookup_type)
        )

    def _lookup_in_store_and_replace_argument(self, replaced):
        if self.store is None:
            self._raise_no_store()
        alias = replaced.value
        replaced.value = self.store.get(alias)

    @staticmethod
    def _raise_no_store():
        msg = "cannot use implicit alias lookup: handler has no store set."
        raise RuntimeError(msg)

    @staticmethod
    def _raise_no_default_argname():
        msg = ("cannot use implicit alias lookup: no lookup argument name "
               "specified and no default name passed to handler.")
        raise ValueError(msg)
